package com.autocare.controller;
import com.autocare.dto.request.*; import com.autocare.dto.response.*; import com.autocare.service.AppointmentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/appointments") public class AppointmentController {private final AppointmentService service; public AppointmentController(AppointmentService s){service=s;} @PostMapping public ResponseEntity<AppointmentResponse> create(@Valid @RequestBody AppointmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping public List<AppointmentResponse> list(@RequestParam(required=false)String status){return service.list(status);}@GetMapping("/{id}") public AppointmentResponse get(@PathVariable String id){return service.get(id);}@PostMapping("/{id}/confirm") public AppointmentResponse confirm(@PathVariable String id){return service.confirm(id);}@PostMapping("/{id}/cancel") public AppointmentResponse cancel(@PathVariable String id){return service.cancel(id);}@PostMapping("/{id}/no-show") public AppointmentResponse noShow(@PathVariable String id){return service.noShow(id);}@PostMapping("/{id}/check-in") public ServiceCaseResponse checkIn(@PathVariable String id){return service.checkIn(id);}}
